public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        long freeThreads = 0, lost = 0;
        for (int i = 0; i < n; i++) {
            long v = next();
            if (v > 0) freeThreads += v;
            else if (freeThreads > 0) freeThreads--;
            else lost++;
        }
        System.out.println(lost);
    }
}

